mapper.insert:

    SELECT
        'MYEX'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(MY_EXP_CODE), LENGTH('MYEX' ) + 1)), 0) + 1, 6, '0')
    FROM MY_EXPERIENCE

INSERT INTO MY_EXPERIENCE (
	MY_EXP_CODE
	, RESUME_NO
	, EXP_CODE
	, EXP_NAME
	, ORGANIZATION_NAME
	, EXP_START_DATE
	, EXP_END_DATE
) VALUES (
	#{myExpCode}
	, #{resumeNo}
	, #{expCode}
	, #{expName}
	, #{organizationName}
	, REPLACE(#{expStartDate}, '-', '')
	, REPLACE(#{expEndDate}, '-', '')
)

mapper.update:
UPDATE MY_EXPERIENCE 
   SET RESUME_NO = #{resumeNo}
       , EXP_CODE = #{expCode}
   	   , EXP_NAME = #{expName}
   	   , ORGANIZATION_NAME = #{organizationName}
   	   , EXP_START_DATE = REPLACE(#{expStartDate}, '-', '')
   	   , EXP_END_DATE = REPLACE(#{expEndDate}, '-', '')
 WHERE MY_EXP_CODE = #{myExpCode}
